(* [comment removed for export] *)
Lemma freed_block_sec : forall L st X LB (p : aptr) mb ms n A n',
  awf L st X -> ablocks L st X LB -> In (HB p A n') LB -> (a_live st) !! p = Some (CSec mb ms n) ->
